// ucd-tools results as fixed tables (generated by tools/gen_ucd.cpp).
#pragma once
#include <cstddef>
#include <cstdint>

namespace propan2ol::ucd_tables {

struct CasePair { uint32_t from, to; };
struct ClauseType { uint32_t cp; int type; };

extern const CasePair ucd_upper[], ucd_lower[];
extern const size_t ucd_upper_count, ucd_lower_count;
extern const ClauseType clause_types[];
extern const size_t clause_types_count;

}  // namespace propan2ol::ucd_tables
